const MAIN_STORAGE_KEY="leadintel_customer_v2_state";
const DISCOVERY_STORAGE_KEY="leadintel_customer_v2_discovery";
const OUTREACH_STORAGE_KEY="leadintel_customer_v2_outreach";
const DELIVERY_STORAGE_KEY="leadintel_customer_v2_delivery";
const DISCOVERY_META_KEY="leadintel_customer_v2_discovery_meta";
const INTELLIGENCE_PROXY="https://apollo-proxy.edgars-7e7.workers.dev";
const MAX_DOSSIER_SEARCH_QUERIES=2;
const MAX_DOSSIER_RESULTS_PER_QUERY=5;
const ASSET_VERSION="20261004-linkedin-message-v1";
const LANGUAGE_ASSET_VERSION="20260924-workspace-content-english-v1";
const asset=path=>`${path}?v=${ASSET_VERSION}`;
const q=id=>document.getElementById(id);
let handoffContact=null;
let outreach=loadOutreach({recoverInterrupted:true});
let scriptRestoreRequest=0;
let scriptGenerationRequest=0;
function contentLanguage(){return LeadIntelContentLanguage.workspaceContentLanguage();}

function esc(value){return String(value??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));}
function readJson(key){try{return JSON.parse(localStorage.getItem(key)||"{}");}catch{return {};}}
function mainState(){return readJson(MAIN_STORAGE_KEY);}
function campaignStudio(){const main=mainState();return LeadIntelOutreach.normalizeCampaignStudio(main.campaignStudio||{},main.profile||{},contentLanguage());}
function persistCampaignStudio(studio,{sync=true}={}){const main=mainState();main.campaignStudio=studio;localStorage.setItem(MAIN_STORAGE_KEY,JSON.stringify(main));window.LeadIntelJourney?.refresh?.();if(sync)window.LeadIntelServerBridge?.saveNow?.().catch(()=>null);return studio;}
function ensureCampaignStudio(){const main=mainState(),studio=campaignStudio();if(JSON.stringify(main.campaignStudio||null)!==JSON.stringify(studio))persistCampaignStudio(studio,{sync:false});return studio;}
function activeCampaignScenario(){const studio=ensureCampaignStudio();return studio.presets.find(item=>item.id===studio.selectedPresetId)||studio.coreScenario;}
function persistMainStep(step){
  const marker=document.querySelector(`[data-step-marker="${step}"]`);
  if(marker&&!marker.classList.contains("active")){marker.dispatchEvent(new MouseEvent("click",{bubbles:true}));return;}
  const main=mainState();main.step=step;localStorage.setItem(MAIN_STORAGE_KEY,JSON.stringify(main));
}
function discoveryState(){return LeadIntelDiscovery.normalizeDiscoveryState(readJson(DISCOVERY_STORAGE_KEY));}
function saveDiscovery(value){localStorage.setItem(DISCOVERY_STORAGE_KEY,JSON.stringify(LeadIntelDiscovery.normalizeDiscoveryState(value)));}
function loadOutreach({recoverInterrupted=false}={}){const state=LeadIntelOutreach.normalizeOutreachState(readJson(OUTREACH_STORAGE_KEY));if(recoverInterrupted)for(const item of state.items){if(['running','checking'].includes(item.localizationStatus)){item.localizationStatus='error';item.localizationApprovalBlocked=true;item.localizationMessage='Generation was interrupted by a reload. Regenerate this package before approval.';}if(item.researchStatus==='running')item.researchStatus='error';}return state;}
function saveOutreach(){outreach=LeadIntelOutreach.normalizeOutreachState(outreach);localStorage.setItem(OUTREACH_STORAGE_KEY,JSON.stringify(outreach));window.LeadIntelJourney?.refresh?.();}
function toast(message){const el=q("toast");if(!el)return;el.textContent=message;el.classList.add("show");clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove("show"),2600);}
function pipeline(){const shared=window.LeadIntelDiscoveryUI?.getSelectedCompanies?.()||window.LeadIntelDiscoveryUI?.getPipeline?.();if(Array.isArray(shared))return shared;const state=discoveryState();return [...new Map([...(state.pipeline||[]),...(state.selectedProspects||[])].map(item=>[item.domain,item])).values()];}
function selectedCandidate(){const domain=outreach.selectedDomain;return pipeline().find(item=>item.domain===domain)||null;}
function currentItem(){return outreach.items.find(item=>item.domain===outreach.selectedDomain)||null;}
function upsertItem(next){const idx=outreach.items.findIndex(item=>item.domain===next.domain);if(idx>=0)outreach.items[idx]=next;else outreach.items.unshift(next);outreach.items=outreach.items.slice(0,50);saveOutreach();return next;}
function stageAtLeast(current,target){const stages=LeadIntelDiscovery.CRM_STAGES;return stages.indexOf(current)>=stages.indexOf(target);}
function updatePipelineStage(domain,targetStage){
  const discovery=discoveryState();const item=discovery.pipeline.find(x=>x.domain===domain);if(!item)return false;
  if(!stageAtLeast(item.stage,targetStage))item.stage=targetStage;
  item.updatedAt=new Date().toISOString();saveDiscovery(discovery);return true;
}
function crmBridge(){return window.LeadIntelServerBridge||null;}
function crmAuthenticated(){const b=crmBridge();return Boolean(b?.session?.authenticated&&b?.workspace);}
function crmDomain(value){return window.LeadIntelCrm?.canonicalDomain(value)||String(value||"").replace(/^https?:\/\//,"").replace(/^www\./,"").split(/[/?#]/)[0].toLowerCase();}
function crmActivityId(kind,domain,stamp){return `${kind}-${crmDomain(domain)}-${String(stamp||"")}`.replace(/[^A-Za-z0-9._:-]/g,"-").slice(0,128);}
async function durableCompany(candidate,{create=true}={}){
  if(!candidate||!crmAuthenticated())return {ok:true,localOnly:true,company:null};
  const b=crmBridge(),workspaceId=b.workspace.id,domain=crmDomain(candidate.domain||candidate.website);const listed=await b.listCrmCompanies({q:domain,limit:20});if(workspaceId!==b.workspace?.id)return {ok:false,error:"Workspace changed; retry in the selected workspace"};if(!listed.ok)return listed;
  let company=(listed.companies||[]).find(row=>crmDomain(row.normalized_domain||row.website)===domain)||null;
  if(!company&&!create)return {ok:true,company:null};
  if(!company){const payload=window.LeadIntelCrm?.mapLocalPipelineItemToCrm(candidate);if(!payload)return {ok:false,error:"CRM mapper unavailable"};const saved=await b.saveCrmCompany(payload);if(!saved.ok)return saved;company=saved.company;}
  return {ok:true,company};
}
async function syncCrmActivity(candidate,{activity=null,stage=""}={}){
  const workspaceId=crmBridge()?.workspace?.id;const resolved=await durableCompany(candidate);if(workspaceId!==crmBridge()?.workspace?.id)return {ok:false,error:"Workspace changed"};if(!resolved.ok||resolved.localOnly)return resolved;const b=crmBridge(),company=resolved.company;
  if(activity){const recorded=await b.recordCrmActivity(company.id,activity);if(!recorded.ok)return recorded;if(workspaceId!==b.workspace?.id)return {ok:false,error:"Workspace changed"};}
  let latest=company;if(stage){const moved=await b.addCrmToPipeline(company.id,stage);if(!moved.ok)return moved;latest=moved.company||company;}
  window.dispatchEvent(new CustomEvent("leadintel:crm-changed",{detail:{company:latest}}));return {ok:true,company:latest};
}

async function saveScriptPackage(){
  const edited=readDraftEdits(),candidate=selectedCandidate();if(!edited?.dossier||!candidate)return;
  if(['running','checking'].includes(edited.localizationStatus)||edited.researchStatus==='running'){toast('Wait for script generation before saving the package to CRM');return;}
  const workspaceId=crmBridge()?.workspace?.id,domain=edited.domain;upsertItem(edited);
  const stamp=new Date().toISOString();
  const result=await syncCrmActivity(candidate,{activity:{id:crmActivityId('scripts-saved',domain,stamp),type:'dossier.built',summary:edited.dossier.selectedTrigger?'Trigger-linked scripts saved':'Company scripts saved',occurred_at:stamp,metadata:{script_package:LeadIntelOutreach.buildCrmScriptSnapshot(edited),selected_trigger:edited.dossier.selectedTrigger||null,selected_person_id:edited.selectedPersonId||''}}});
  if(workspaceId!==crmBridge()?.workspace?.id||domain!==outreach.selectedDomain)return;
  q('trigger-script-status').textContent=result.ok&&!result.localOnly?'Scripts and trigger connection saved to CRM.':'Scripts remain in this browser. Sign in or retry CRM save.';
}
async function restoreScriptPackage(){
  const candidate=selectedCandidate();if(!candidate||!crmAuthenticated())return;
  const request=++scriptRestoreRequest,workspaceId=crmBridge().workspace.id,domain=candidate.domain;
  const resolved=await durableCompany(candidate,{create:false});if(!resolved.ok||!resolved.company){q('trigger-script-status').textContent='No saved CRM company package yet.';return;}
  if(request!==scriptRestoreRequest||workspaceId!==crmBridge()?.workspace?.id||domain!==outreach.selectedDomain)return;
  const detail=await crmBridge().getCrmCompany(resolved.company.id);
  if(request!==scriptRestoreRequest||workspaceId!==crmBridge()?.workspace?.id||domain!==outreach.selectedDomain)return;
  if(!detail.ok){q('trigger-script-status').textContent='CRM package could not load. Your current scripts are unchanged.';return;}
  const activities=detail.activities||[];let cursor=detail.activity_next_cursor;const cursors=new Set();
  while(!activities.some(activity=>activity.metadata?.script_package)&&cursor&&!cursors.has(cursor)){
    cursors.add(cursor);const page=await crmBridge().getCrmActivities(resolved.company.id,{limit:100,cursor});
    if(request!==scriptRestoreRequest||workspaceId!==crmBridge()?.workspace?.id||domain!==outreach.selectedDomain)return;
    if(!page.ok){q('trigger-script-status').textContent='CRM history could not load. Your current scripts are unchanged.';return;}
    activities.push(...(page.activities||[]));cursor=page.next_cursor;
  }
  const saved=activities.find(activity=>activity.metadata?.script_package);
  const item=LeadIntelOutreach.restoreCrmScriptSnapshot(saved?.metadata?.script_package,domain);
  if(!item){q('trigger-script-status').textContent='No saved script package for this company yet.';return;}
  scriptGenerationRequest++;upsertItem(item);renderDossier();q('trigger-script-status').textContent='Saved scripts and trigger connection reopened from CRM.';
}
async function loadTriggerAlerts(){
  const candidate=selectedCandidate(),item=currentItem(),bridge=crmBridge();if(!candidate||!item?.dossier||!crmAuthenticated()){toast('Sign in and build the company dossier first');return;}
  const domain=candidate.domain,workspaceId=bridge.workspace.id;
  try{
    const response=await fetch(`https://leadintel-api.edgars-7e7.workers.dev/api/market-monitoring/alerts?workspace_id=${encodeURIComponent(workspaceId)}`,{credentials:'include',headers:{Accept:'application/json'}});
    const result=await response.json();if(!response.ok)throw Error(result.error||'Monitoring alerts unavailable');
    if(workspaceId!==crmBridge()?.workspace?.id||domain!==outreach.selectedDomain)return;
    q('trigger-monitoring-alerts').innerHTML=(result.alerts||[]).map(alert=>`<article><a href="${esc(alert.source_url)}" target="_blank" rel="noopener">${esc(alert.title)}</a><p>${esc(alert.summary)}</p><small>Detected: ${esc(alert.created_at)} · source date unknown · company association needs review</small><button class="secondary-btn small" type="button" data-add-trigger-alert="${esc(alert.id)}">Review for ${esc(candidate.company)}</button></article>`).join('')||'<p>No monitoring alerts yet.</p>';
    q('trigger-monitoring-alerts').onclick=event=>{const button=event.target.closest('[data-add-trigger-alert]');if(!button||domain!==outreach.selectedDomain||workspaceId!==crmBridge()?.workspace?.id)return;const alert=(result.alerts||[]).find(row=>row.id===button.dataset.addTriggerAlert);if(!alert)return;const current=currentItem();if(!current?.dossier)return;const evidence={url:alert.source_url,title:alert.title,description:alert.summary,text:alert.summary,date:'',detectedAt:alert.created_at,sourceType:'Public'};current.dossier.evidence=[...(current.dossier.evidence||[]).filter(row=>row.url!==alert.source_url),evidence].slice(-15);upsertItem(current);renderDossier();q('outreach-trigger-select').value=alert.source_url;previewSelectedTrigger();};
  }catch(error){q('trigger-script-status').textContent=error.message;}
}
function previewSelectedTrigger(){const item=currentItem(),url=q('outreach-trigger-select')?.value;const source=item?.dossier?.evidence?.find(row=>row.url===url);q('trigger-source-preview').innerHTML=source?`<a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.title||source.url)} ↗</a><br>Source date: ${esc(source.date||'unknown')}<br>${esc(String(source.text||source.description||'').slice(0,900))}`:'Select and review a source before connecting it to scripts.';q('trigger-source-confirm').checked=false;}
async function useReviewedTrigger(){
  const current=currentItem();if(!current?.dossier)return;
  if(!q('trigger-source-confirm').checked){toast('Confirm that you checked the source, company and event first');return;}
  try{const item=LeadIntelOutreach.reviewTrigger(current,q('outreach-trigger-select').value);upsertItem(item);const generated=await regenerateDrafts();if(!generated)return;q('trigger-script-status').textContent=generated.localizationApprovalBlocked?'Trigger selected; resolve the script language before approval.': 'Reviewed trigger connected to the selected buyer. Save scripts to CRM to preserve the connection.';}catch(error){toast(error.message);}
}

