function showStep(step){persistMainStep(step);document.querySelectorAll(".step-view").forEach(el=>el.classList.toggle("active",Number(el.dataset.step)===step));document.querySelectorAll("[data-step-marker]").forEach(el=>{const n=Number(el.dataset.stepMarker);el.classList.toggle("active",n===step);el.classList.toggle("complete",n<step);});window.scrollTo({top:0,behavior:"smooth"});}
function showOutreachStep(){ensureSelection();renderAll();showStep(6);}
function continueFromCompanies(){
  const stage=Number(q("continue-to-outreach")?.dataset.journeyStage)||5;
  if(stage===6&&window.LeadIntelDiscoveryUI?.continueToMessages){window.LeadIntelDiscoveryUI.continueToMessages();return;}
  if(window.LeadIntelJourney?.openWorkflowStage){window.LeadIntelJourney.openWorkflowStage(stage);return;}
  if(stage===5){window.LeadIntelDiscoveryUI?.open?.({focus:"buyers"});return;}
  showOutreachStep();
}
function backToDiscovery(){try{const meta=readJson(DISCOVERY_META_KEY);localStorage.setItem(DISCOVERY_META_KEY,JSON.stringify({...meta,activeJourneyStage:5,visibleStep:5}));}catch{}if(window.LeadIntelJourney?.openWorkflowStage){window.LeadIntelJourney.openWorkflowStage(5);return;}if(window.LeadIntelDiscoveryUI?.open){window.LeadIntelDiscoveryUI.open({focus:"buyers"});return;}showStep(5);}
