  const language=contentLanguage(),campaign=activeCampaignScenario();const dossierCandidate=handoffContact&&handoffContact.domain===candidate.domain?{...candidate,people:(candidate.people||[]).filter(p=>handoffContact.channel!=='linkedin'||p.id===handoffContact.personId).map(p=>p.id===handoffContact.personId?{...p,...handoffContact.contact,id:p.id,name:handoffContact.contact.name||p.name,email:handoffContact.contact.work_email||handoffContact.contact.normalized_email}:p)}:candidate;let dossier=LeadIntelOutreach.buildOpportunityDossier(dossierCandidate,main.profile||{},main.market||{},research,language);const choice=readJson(DISCOVERY_META_KEY).scriptBuyer;const contact=dossierCandidate.people?.find(p=>p.id===choice?.personId)||dossierCandidate.people?.[0]||null;
  item=LeadIntelOutreach.invalidateOutreachApproval({...item,dossier,campaignScenario:campaign,researchStatus:research.length?(failures?"partial":"complete"):"error",researchAt:new Date().toISOString(),selectedPersonId:contact?.id||"",drafts:LeadIntelOutreach.buildOutreachDrafts(dossier,contact,main.profile||{},campaign.tone||"consultative",language,campaign),contentLanguage:language});item=await prepareLocalizedItem(item,campaign,candidate);if(!item)return;upsertItem(item);
